export class LiveSession{
 constructor({createReader,onSnapshot,onBatch,onStatus,schedule=(fn,ms)=>setTimeout(fn,ms),cancel=id=>clearTimeout(id)}){Object.assign(this,{createReader,onSnapshot,onBatch,onStatus,schedule,cancel});this.reader=null;this.active=false;this.busy=false;this.timer=null;this.failures=0;this.successes=0;this.lastSuccess=null;}
 setActive(active){this.active=active;this.cancel(this.timer);this.timer=null;if(!active){this.reader?.suspend();return;}this.reader?.resume();if(!this.busy)this.run();}
 async run(){if(!this.active||this.busy)return;this.busy=true;try{this.reader??=await this.createReader();if(!this.active){this.reader.suspend();return;}this.reader.resume();const batch=await this.reader.poll(s=>{if(this.active)this.onSnapshot(s);});if(!this.active)return;if(batch)this.onBatch(batch);this.failures=0;this.successes++;this.lastSuccess=Date.now();this.onStatus({state:this.reader.recovery?.target?'recovering':'ready',lastSuccess:this.lastSuccess,verifiedThroughBlock:this.reader.recovery?.cursor?.toString()});}catch(error){if(this.active){this.failures++;this.onStatus({state:'error',message:error.message,lastSuccess:this.lastSuccess});}}finally{this.busy=false;if(this.active)this.timer=this.schedule(()=>this.run(),Math.min(120000,15000*2**Math.min(this.failures,3)));}}
}
